-- Chike's Creative Space - Pic-a-Puzzle on the Play page, for subscribers only (like Gravity 4).
-- Safe to re-run. Nothing here sends an email.
--
-- The game's code is not a public file: it lives in the admin-only portal_game_files table (row pg-picture-puzzle,
-- source supabase/private-games/pic-pop-puzzle.html), handed out only to signed-in subscribers as the example at the
-- top of AI Lesson 04 (supabase/ai-lesson-picture-puzzle.sql). This row only puts a card with a lock on the Play page;
-- its page sends visitors to that lesson, where the portal's own gate asks them to join first.

insert into games (id, data) values ('game-pic-pop-puzzle', $j${"id":"game-pic-pop-puzzle","title":"Pic-a-Puzzle","slug":"pic-pop-puzzle","kind":"members","summary":"Turn any picture into a puzzle, then put it back together.","players":"1","minutes":10,"ageMin":5,"ageMax":12,"rules":["Start with one of the 3 drawings, or press Upload your own image to use a photo or drawing. It stays on your device and is never shared.","Pick how many pieces: Easy, Medium, Hard or Wizard.","Drag a piece onto another piece to swap them. On a phone or tablet, tap one piece, then tap another.","With a keyboard: use the arrow keys to move around the board, press Enter to pick up a piece, the arrow keys to slide it into place, and Enter to put it down.","A piece in the right spot turns green and stays put.","Stuck? Press Peek at it to see the whole picture for 2 seconds, or Shuffle again for a fresh start.","Finish the picture to see your time and moves, then try a harder one!"],"leadsTo":"","interactive":true,"path":"","icon":"puzzle","p1":"#CDDFE4","p2":"#1273B0","status":"published","featured":false,"badge":"New","order":0,"vocabWord":"2D spatial awareness","vocabSay":"too-DEE SPAY-shul uh-WAIR-ness · noun","vocabMeaning":"Knowing where things are on a flat surface, and seeing how the pieces fit together to make a whole picture.","vocabExample":"In Pic-a-Puzzle, your 2D spatial awareness helps you spot where each piece belongs: sky at the top, grass at the bottom!","createdAt":"2026-11-01T12:00:00.000Z","updatedAt":"2026-11-01T12:00:00.000Z","cover":{"src":"assets/games/pic-pop-puzzle.jpg","alt":"A drawing of kids building a toy city with a train in a treehouse, cut into puzzle pieces, with one piece lifted out of place and one locked in with a green border"},"portalSlug":"how-to-build-your-own-puzzle-game"}$j$::jsonb)
on conflict (id) do update set data = excluded.data, updated_at = now();
